# ============================================================
# 场景9：删除任务生命周期合并场景（无后处理）
# 合并覆盖原三条独立场景：
# 1. 删除已提交任务-清洁流程无后处理：首次删除应失败
# 2. 删除已完成的任务：模型撤回后，任务回到可删除状态
# 3. 删除已创建的任务：最终删除深度训练任务成功
# ============================================================
DELETE_SUBMITTED_NO_POSTPROCESS_SCENARIOS = [
    {
        "name": "删除任务生命周期-提交失败撤回后删除",
        "cut_value": 1024,
        "train_epoch": 30,
        "train_batch_size": 16,
        "train_lr": 0.0002,
        "expect_first_delete_fails": True,
        "expect_first_delete_error": "有已提交模型，不允许删除",
        "expect_model_withdraw_succeeds": True,
        "expect_second_delete_succeeds": True,
        "covers": ["删除已创建的任务", "删除已完成的任务", "删除已提交任务-清洁流程无后处理"],
        "remark": "合并删除场景：已提交任务先拒绝删除，撤回模型后训练任务可删除，减少重复造数耗时",
    },
]
